      "summary": "O operador registra luz dentro de uma torre sem lente.",
      "content": "O operador registra luz dentro de uma torre sem lente.\n\nA emissão não alcançava o mar. O clarão parecia descer pela escada interna, contrariando a geometria da lanterna. Nunes recusou classificar o evento como pane elétrica e anotou três nomes ouvidos no ruído branco.\n\nO registro foi preservado com cadeia de custódia incompleta. Uma revisão posterior contradiz parte dos horários sem invalidar a ocorrência.",
