      "summary": "A Guarda Costeira solicita apoio sem reconhecer São Firmo no cabeçalho.",
      "content": "A Guarda Costeira solicita apoio sem reconhecer São Firmo no cabeçalho.\n\nO pedido cita deriva de bússolas, neblina imóvel e uma frequência que repete o prefixo da própria embarcação. A coordenada foi removida na segunda revisão, mas permanece impressa ao contrário no rodapé.\n\nO registro foi preservado com cadeia de custódia verificada. As referências cruzadas permanecem disponíveis conforme o nível de acesso.",
