      "content": "Chuva registrada de baixo para cima durante onze minutos.\n\nSensores indicaram pressão estável e vento nulo. As gotas retornaram às nuvens sem molhar o cais; duas testemunhas, porém, chegaram à enfermaria com os pulmões cheios de água salgada.\n\nO registro foi preservado com cadeia de custódia verificada. As referências cruzadas permanecem disponíveis conforme o nível de acesso.",
