      "content": "Ritos costeiros anteriores à construção da capela.\n\nOs moradores não rezavam para que barcos retornassem, mas para que o farol esquecesse seus nomes. O sino era tocado apenas quando a torre permanecia apagada.\n\nO registro foi preservado com cadeia de custódia verificada. As referências cruzadas permanecem disponíveis conforme o nível de acesso.",
